    await promptMovement(line, event, next, `✅ Item saved\nRoute: Home → ${savedShop}\nQuantity: ${state.quantity}\nPhoto: saved\n${photoCountText}${state.remark ? `\nBreakdown / note:\n${state.remark}` : ""}\n\n`);
